#!/usr/bin/env bash
set -euo pipefail
umask 077

if [[ $# -lt 1 || $# -gt 2 || (${2:-} != "" && ${2:-} != "--restart") ]]; then
  printf 'Usage: %s <kubectl-context> [--restart]\n' "$0" >&2
  exit 2
fi

deployment="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
private="$deployment/private/minio"
kubectl=(kubectl --context "$1" -n omni)
remote=minio.omni.svc:9000
origin="https://$remote"
port=${MINIO_VERIFY_PORT:-19000}
bucket=omnirelay-files
key="deployment-check/$(openssl rand -hex 8)"
payload=$(openssl rand -hex 16)
# The file is generated by apply-object-storage.sh on this host.
source "$private/root.env"
forward_log=$(mktemp "$private/port-forward.XXXXXX")
sample_file=$(mktemp "$private/s3-sample.XXXXXX")
printf '%s' "$payload" > "$sample_file"
forward_pid=
close_forward() {
  if [[ -n "$forward_pid" ]]; then
    kill "$forward_pid" 2>/dev/null || true
    wait "$forward_pid" 2>/dev/null || true
    forward_pid=
  fi
}
cleanup() {
  close_forward
  unlink "$forward_log"
  unlink "$sample_file"
}
trap cleanup EXIT
curl_args=(--silent --show-error --noproxy '*' --max-time 6 --cacert "$private/ca.crt"
  --connect-to "$remote:127.0.0.1:$port")

open_forward() {
  "${kubectl[@]}" port-forward --address 127.0.0.1 service/minio "$port:9000" > "$forward_log" 2>&1 &
  forward_pid=$!
  for ((try=0; try<25; try++)); do
    if curl "${curl_args[@]}" --fail "$origin/minio/health/ready" >/dev/null 2>&1; then
      return
    fi
    if ! kill -0 "$forward_pid" 2>/dev/null; then
      cat "$forward_log" >&2
      return 1
    fi
    sleep 1
  done
  printf 'The S3 readiness endpoint did not respond.\n' >&2
  return 1
}

s3() {
  printf 'user = "%s:%s"\n' "$MINIO_ROOT_USER" "$MINIO_ROOT_PASSWORD" |
    curl "${curl_args[@]}" --config - --aws-sigv4 aws:amz:us-east-1:s3 "$@"
}

open_forward
code=$(s3 --head --output /dev/null --write-out '%{http_code}' "$origin/$bucket")
case "$code" in
  200) ;;
  404) s3 --fail --request PUT "$origin/$bucket" >/dev/null ;;
  *) printf 'Bucket lookup returned HTTP %s.\n' "$code" >&2; exit 1 ;;
esac
s3 --fail --upload-file "$sample_file" "$origin/$bucket/$key" >/dev/null
test "$(s3 --fail "$origin/$bucket/$key")" = "$payload"
anonymous=$(curl "${curl_args[@]}" --output /dev/null --write-out '%{http_code}' "$origin/$bucket/$key")
test "$anonymous" = 403
printf 'S3 HTTPS and CA verification passed. Signed write/read worked and anonymous read returned 403.\n'

if [[ ${2:-} = "--restart" ]]; then
  previous=$("${kubectl[@]}" get pod minio-0 -o jsonpath='{.metadata.uid}')
  close_forward
  "${kubectl[@]}" rollout restart statefulset/minio
  "${kubectl[@]}" rollout status statefulset/minio --timeout=90s
  current=$("${kubectl[@]}" get pod minio-0 -o jsonpath='{.metadata.uid}')
  test "$previous" != "$current"
  open_forward
  test "$(s3 --fail "$origin/$bucket/$key")" = "$payload"
  printf 'A replacement pod read the same object from the persistent volume.\n'
fi

s3 --fail --request DELETE "$origin/$bucket/$key" >/dev/null
